// 1. Place 7-Minute Temporary Seat Hold
POST /api/v1/shows/shw_9912/holds
Headers:
  Idempotency-Key: hold_usr441_shw9912
  X-Waiting-Room-Token: eyJhbGciOiJFZERTQSJ9.
Request:
{
  "user_id": "usr_441",
  "seat_ids": ["A-12", "A-13"]
}
Response (201 Created: or 409 Conflict if already held):
{
  "booking_id": "bkg_77812",
  "status": "HELD",
  "seat_ids": ["A-12", "A-13"],
  "hold_expires_at": "2026-09-30T16:37:00Z",
  "checkout_Remaining_seconds": 420
}

// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY events_shows (PostgreSQL + Read Replicas) {
  [PK ] show_id                UUID
  [IDX] venue_id               UUID
        title                  VARCHAR(255)
        start_time             TIMESTAMPTZ
        total_seats            INT
}

ENTITY show_seats (PostgreSQL (ACID + Optimistic Lock)) {
  [PK ] show_id                UUID (Composite PK)
  [PK ] seat_id                VARCHAR(16) (Composite PK)
        status                 ENUM('AVAILABLE','HELD','BOOKED')
  [IDX] hold_expires_at        TIMESTAMPTZ
        version                INT (OCC Lock)
}

ENTITY bookings (PostgreSQL (Transactional)) {
  [PK ] booking_id             UUID
  [FK ] show_id                UUID
  [IDX] user_id                UUID
        seat_ids               ARRAY<VARCHAR>
        payment_status         ENUM('PENDING','PAID')
}

// Relationships: events_shows --(1 : N (contains seats))--> show_seats --(1 : N (reserves & books))--> bookings
